import { z } from "zod";

export const NOTICE_UNIT_MINUTES = { minutes: 1, hours: 60, days: 1440 } as const;

export const LOCATION_TYPES = ["none", "in_person", "phone", "custom_link", "google_meet", "zoom", "microsoft_teams"] as const;

// Location types whose value the host types in; the rest are generated by an integration.
export const LOCATION_VALUE_TYPES = ["in_person", "phone", "custom_link"] as const;

const PHONE_PATTERN = /^\+?[0-9 ()\-.]{6,32}$/;

function isHttpUrl(value: string) {
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

export const eventTypeSchema = z
  .object({
    title: z.string().trim().min(2, "Title must be at least 2 characters").max(120),
    description: z.string().max(2000).optional(),
    duration_option: z.enum(["15", "30", "45", "60", "custom"]),
    custom_duration_minutes: z
      .number()
      .int("Enter a whole number")
      .min(5)
      .max(480)
      .optional(),
    slot_interval_minutes: z.number().int().min(5).max(480),
    price: z.number().int("Enter a whole number").min(0),
    is_active: z.boolean(),
    is_default: z.boolean(),
    buffer_before_minutes: z.number({ message: "Enter minutes" }).int("Enter a whole number").min(0).max(240, "Use 240 minutes or fewer"),
    buffer_after_minutes: z.number({ message: "Enter minutes" }).int("Enter a whole number").min(0).max(240, "Use 240 minutes or fewer"),
    minimum_notice_value: z.number({ message: "Enter a number" }).int("Enter a whole number").min(0),
    minimum_notice_unit: z.enum(["minutes", "hours", "days"]),
    max_days_in_advance: z.number({ message: "Enter a number of days" }).int("Enter a whole number").min(1).max(730, "Use 730 days or fewer").nullable(),
    daily_booking_limit: z.number({ message: "Enter a number" }).int("Enter a whole number").min(1).max(100, "Use 100 or fewer").nullable(),
    location_type: z.enum(LOCATION_TYPES),
    location_value: z.string().trim().max(2048),
  })
  .superRefine((eventType, context) => {
    if (
      eventType.duration_option === "custom"
      && eventType.custom_duration_minutes === undefined
    ) {
      context.addIssue({
        code: "custom",
        message: "Enter a custom duration",
        path: ["custom_duration_minutes"],
      });
    }
  })
  .superRefine((eventType, context) => {
    const value = eventType.location_value;
    const addIssue = (message: string) => context.addIssue({ code: "custom", message, path: ["location_value"] });
    if (eventType.location_type === "in_person") {
      if (!value) addIssue("Enter the meeting address");
      else if (value.length > 500) addIssue("Keep the address under 500 characters");
    }
    if (eventType.location_type === "phone" && !PHONE_PATTERN.test(value)) {
      addIssue("Enter a valid phone number");
    }
    if (eventType.location_type === "custom_link" && !isHttpUrl(value)) {
      addIssue("Enter a valid meeting link starting with https://");
    }
  })
  .refine(
    (eventType) => eventType.minimum_notice_value * NOTICE_UNIT_MINUTES[eventType.minimum_notice_unit] <= 43200,
    { message: "Minimum notice can be at most 30 days", path: ["minimum_notice_value"] },
  )
  .refine((eventType) => !eventType.is_default || eventType.is_active, {
    message: "A default booking must be visible on your booking page",
    path: ["is_default"],
  });

export type EventTypeFormValues = z.infer<typeof eventTypeSchema>;
